def run(path):
    s=open(path,encoding='utf-8').read()
    for n,d in S.items():
        s=apply_step(s,W,n,d['lbl'],d['cards'],guides=d.get('guides'),gguide=d.get('gguide'))
    open(path,'w',encoding='utf-8').write(s);print('ok',list(S))
if __name__=='__main__': run(sys.argv[1])
